import json,sys
for line in sys.stdin:
 message=json.loads(line)
 request_id=message.get('id')
 if request_id is None: continue
 method=message.get('method')
 if method=='initialize': result={'protocolVersion':'2025-03-26','capabilities':{'tools':{}},'serverInfo':{'name':'local-hello','version':'1.0.0'}}
 elif method=='tools/list': result={'tools':[{'name':'hello','description':'Return a greeting for the supplied name.','inputSchema':{'type':'object','properties':{'name':{'type':'string'}},'additionalProperties':False}}]}
 elif method=='tools/call':
  name=message.get('params',{}).get('arguments',{}).get('name','world')
  result={'content':[{'type':'text','text':'Hello, '+str(name)+'!'}],'isError':False}
 else:
  print(json.dumps({'jsonrpc':'2.0','id':request_id,'error':{'code':-32601,'message':'Method not supported'}}),flush=True)
  continue
 print(json.dumps({'jsonrpc':'2.0','id':request_id,'result':result}),flush=True)
